<?php
/**
 * notd configuration: defaults.
 *
 * Do not edit this file to change settings. Create `config.local.php` next to
 * it (it is ignored by git, so updates never overwrite it) and define only the
 * constants you want to change, e.g.
 *
 *     <?php
 *     define('ACTIVE_THEME', 'darkly');
 *     define('DB_PATH', '/home/me/notes/notd.sqlite');
 *
 * See config.local.example.php for the full list.
 */

if (is_file(__DIR__ . '/config.local.php')) {
    require_once __DIR__ . '/config.local.php';
}

/** Defines a constant unless config.local.php already did. */
function notd_default(string $name, $value): void
{
    if (!defined($name)) {
        define($name, $value);
    }
}

// --- Paths ---
// NOTD_DB_PATH is read from the server/CLI environment (never from a request),
// which lets tests and scripts point at another database.
notd_default('DB_PATH', getenv('NOTD_DB_PATH') ?: __DIR__ . '/db/database.sqlite');
notd_default('UPLOADS_DIR', __DIR__ . '/uploads');

// --- Features ---
notd_default('ACTIVE_THEME', 'default');            // a file name in assets/css/themes/ (without .css)
notd_default('WEBHOOKS_ENABLED', true);             // master switch for all webhook dispatches
notd_default('ADVANCED_QUERY_MODE', false);         // true lifts the pattern restrictions on SQL{...} queries (still read-only)
notd_default('ACTIVE_EXTENSIONS', ['attachment_dashboard', 'pomodoro_timer', 'kanban_board']); // folder names in extensions/
notd_default('TASK_STATES', ['TODO', 'DOING', 'DONE', 'SOMEDAY', 'WAITING', 'CANCELLED']);

// Weight given to the properties the backend derives from note content.
notd_default('SPECIAL_STATE_WEIGHTS', [
    'SQL' => 3,
    'TASK' => 4,
    'DONE_AT' => 3,
    'TRANSCLUSION' => 3,
    'LINK' => 3,
    'URL' => 3
]);

// --- Property System Configuration ---
// The behaviour of a property depends on its 'weight': the number of colons in
// its syntax. The frontend uses the visibility flags; the backend uses
// 'update_behavior' to maintain the Properties index.
notd_default('PROPERTY_WEIGHTS', [
    // Default Public Property (e.g., {key::value})
    2 => [
        'label' => 'Public',
        'description' => 'Standard properties visible in all views.',
        'update_behavior' => 'replace', // On update, the old value in the DB is replaced with the new one.
        'visible_in_view_mode' => true,   // Frontend should show this in read-only views.
        'visible_in_edit_mode' => true    // Frontend should show this in editable views.
    ],
    // Internal Property (e.g., {key:::value})
    3 => [
        'label' => 'Internal',
        'description' => 'Properties for internal logic, hidden by default.',
        'update_behavior' => 'replace', // Replace the value on update.
        'visible_in_view_mode' => false,  // Changed from false to true
        'visible_in_edit_mode' => true    // Frontend should SHOW this in editable views.
    ],
    // System/Log Property (e.g., {key::::value})
    4 => [
        'label' => 'System Log',
        'description' => 'Properties that act as an immutable log or history.',
        'update_behavior' => 'append',  // On update, a NEW row is added to the DB, preserving the old one.
        'visible_in_view_mode' => false,  // Frontend should HIDE this in read-only views.
        'visible_in_edit_mode' => false   // Frontend should HIDE this in editable views.
    ]
    // You can add more weights here, e.g., weight 5 for "Archived" properties.
]);

// --- Errors ---
// With NOTD_DEBUG on, PHP errors are displayed and API error responses carry
// file names and stack traces. Leave it off unless you are developing.
notd_default('NOTD_DEBUG', false);
ini_set('display_errors', NOTD_DEBUG ? '1' : '0');
ini_set('display_startup_errors', NOTD_DEBUG ? '1' : '0');
error_reporting(E_ALL);

// --- Timezone ---
// Timestamps are stored in UTC.
date_default_timezone_set('UTC');

// --- Global Error and Exception Handling ---
// A PHP error or uncaught exception becomes a JSON error response instead of
// a blank page or an HTML dump. Details are always written to the error log.
function notd_fail(string $message, array $details): void
{
    error_log('[notd] ' . $details['type'] . ': ' . $details['message'] . ' in ' . $details['file'] . ':' . $details['line']);
    if (PHP_SAPI === 'cli') {
        fwrite(STDERR, $details['type'] . ': ' . $details['message'] . ' in ' . $details['file'] . ':' . $details['line'] . "\n");
    } elseif (!headers_sent()) {
        http_response_code(500);
        header('Content-Type: application/json');
        $body = ['status' => 'error', 'message' => $message];
        if (NOTD_DEBUG) {
            $body['details'] = $details;
        }
        echo json_encode($body);
    }
    exit(1);
}

set_error_handler(function ($errno, $errstr, $errfile, $errline) {
    if (!(error_reporting() & $errno)) {
        return false;
    }
    notd_fail('An internal server error occurred.', [
        'type' => 'PHP Error', 'message' => $errstr, 'file' => $errfile, 'line' => $errline,
    ]);
});

set_exception_handler(function ($e) {
    notd_fail('An internal server error occurred.', [
        'type' => get_class($e), 'message' => $e->getMessage(), 'file' => $e->getFile(), 'line' => $e->getLine(),
        'trace' => explode("\n", $e->getTraceAsString()),
    ]);
});
